/// <summary>
/// The <c>WHSReleaseToWarehouseService</c> class exposes services for auto shipment creation.
/// </summary>
public class MetTransferOrderAutoShipService
{
    #OCCRetryCount

    WHSReleaseToWarehouseRetrieveRTWId  retrieveRTWId;
    WHSTmpReleaseToWarehouse            releaseToWarehouse;
    private WHSReleaseToWarehouseId     releaseToWarehouseIdGlobal;
    private boolean                     errorsFound;

   
   

}

Method.Source:
    private void autoTransferShipmentCreation(
        InventTransferTable _transferTable, 
        MetTransferOrderAutoShipContract _contract)
    {
        setPrefix(strFmt("@SYP4860552", _transferTable.TransferId));
        
        try
        {
            ttsBegin;
            ttscommit;


        }
        catch (Exception::Error)
        {
            //error(WHSWarehouseRelease::cannotReleaseTransferMessage(_transferTable));
            errorsFound = true;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() != 0)
            {
                throw Exception::UpdateConflict;
            }
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            retry;
        }
        catch
        {
            if (appl.ttsLevel() != 0)
            {
                throw error(strFmt("@SYS330665", funcName()));
            }

            exceptionTextFallThrough();
        }

    }

    /// <summary>
    /// Auto ship TO
    /// </summary>
    /// <param name="_contract">
    /// Parameters
    /// </param>
    /// <exception cref="Exception::Error">
    /// Throws an error if the specified contract is not valid.
    /// </exception>
    /// <exception cref="Exception::Error">
    /// Throws an error if called in transaction scope.
    /// </exception>
    public void autoShipTransferOrders(MetTransferOrderAutoShipContract _contract)
    {
        errorsFound = false;

        if (!_contract.validate())
        {
            throw error("@SYS78886");
        }

        this.checkTTSLevel();


        QueryRun queryRunTransfers = new QueryRun(this.finalTransferOrdersReleaseQuery(_contract));
                  
       
        int processedTransferOrders = 0;
        while (queryRunTransfers.next())
        {
            InventTransferTable inventTransferTable = queryRunTransfers.get(tableNum(InventTransferTable));
           // this.autoReleaseTransferOrder(inventTransferTable, _contract);

            processedTransferOrders++;
        }

    }

private void checkTTSLevel()
{
    if (appl.ttsLevel() != 0)
    {
        // The auto release job is using transaction management for rolling back reservations in cases of release failure.
        // Also infinite loop problems can happen when running the auto release functionality within a transaction scope.
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}

    private Query finalTransferOrdersReleaseQuery(MetTransferOrderAutoShipContract _contract)
    {
        Query query = _contract.parmQuery();
        ////QueryBuildDataSource  dsTransferLines = query.dataSourceTable(tableNum(InventTransferTable)).addDataSource(tableNum(InventTransferLine));
        ////dsTransferLines.relations(true);
        ////dsTransferLines.joinMode(JoinMode::ExistsJoin);
        ////dsTransferLines.addRange(fieldNum(InventTransferLine, QtyRemainShip)).value('>0');

        return query;
    }
